            /* ───────── 6. The invoice ───────── */

            'luma_os_invoice_what' => [
                'b' => 6, 'title' => 'What is the invoice', 'title_tl' => 'Ano ang invoice',
                'say' => [
                    'en'  => ['invoice', 'what is an invoice', 'what is in my invoice', 'why do i get an invoice', 'explain the invoice', 'what does the invoice show'],
                    'tl'  => ['ano ang invoice', 'ano po ang laman ng invoice', 'bakit may invoice', 'ipaliwanag ang invoice', 'ano ang nakasulat sa invoice', 'para saan ang invoice'],
                    'mix' => ['invoice po', 'ano yung invoice', 'bakit may invoice ako', 'explain po yung invoice', 'what is invoice po', 'para saan yung invoice'],
                ],
                'kw' => 'invoice, invoys, what&invoice, explain&invoice, invoice&show, invoice&laman, ano&invoice, para saan&invoice, bakit&invoice, why&invoice, inside&invoice, about&invoice, the invoice',
                'en' => "The invoice is the bill for your Other Services work. It lists the service, the price, any visit or pickup fee, the total and the payment plan. Our team sends it after reviewing your ticket. You pay it online or in cash, and its status shows Sent, Paid or Cancelled.",
                'tl' => "Ang invoice po ay ang singil para sa inyong Other Services na trabaho. Nakasulat dito ang serbisyo, presyo, anumang bayad sa pagpunta o pagkuha, ang kabuuan at ang plano ng bayad. Ipinapadala ito ng aming team pagkatapos tingnan ang ticket ninyo. Babayaran ninyo ito online o cash, at ang status nito ay Sent, Paid o Cancelled.",
                'next' => ['luma_os_invoice_find', 'luma_os_invoice_status_words', 'luma_os_pay_how', 'luma_os_invoice_print'],
            ],

