                'say' => [
                    'en'  => ['where is my invoice', 'where can i find my invoice', 'i did not receive my invoice', 'how do i see my invoice', 'show my invoice', 'my invoice is missing'],
                    'tl'  => ['nasaan ang invoice ko', 'saan ko makikita ang invoice', 'hindi ko natanggap ang invoice', 'paano makita ang invoice ko', 'ipakita ang invoice ko', 'wala po akong invoice'],
                    'mix' => ['asan na invoice ko po', 'where po makikita ang invoice', 'wala pa akong na receive na invoice', 'pano makita ang invoice', 'show invoice ko', 'nawawala yung invoice ko'],
                ],
                'kw' => 'where&invoice, find&invoice, see&invoice, show&invoice, my invoice, missing&invoice, invoice&missing, nawawala&invoice, wala&invoice, nasaan&invoice, saan&invoice, makita&invoice, receive&invoice, natanggap&invoice, received&invoice, hindi natanggap&invoice, did not receive&invoice, no invoice, view invoice, open invoice, ipakita&invoice',
                'en' => "You can find your invoice in your account under Service Request. It shows once our team has sent it, and you also get a notification when it is ready. If your ticket is still being reviewed, there is no invoice yet.",
                'tl' => "Makikita po ninyo ang invoice sa inyong account sa Service Request. Lumalabas ito kapag naipadala na ng aming team, at makakatanggap din kayo ng notification kapag handa na ito. Kung sinusuri pa ang ticket ninyo, wala pa pong invoice.",
