                'handler' => 'status_invoice',
                'buttons' => [['Open my service requests', 'Buksan ang aking service requests', 'services.request']],
            ],

            'luma_os_invoice_status_words' => [
                'b' => 6, 'title' => 'Invoice statuses', 'title_tl' => 'Mga status ng invoice',
                'say' => [
                    'en'  => ['what does sent mean on my invoice', 'what does paid mean', 'what does a cancelled invoice mean', 'invoice status meaning', 'what do the invoice statuses mean', 'my invoice status says cancelled what does it mean'],
                    'tl'  => ['ano ang ibig sabihin ng sent sa invoice', 'ano ang ibig sabihin ng paid', 'ano ang ibig sabihin ng cancelled sa invoice', 'ibig sabihin ng status ng invoice', 'ano ang mga status ng invoice', 'ano po ang cancelled na status'],
                    'mix' => ['ano meaning ng sent sa invoice', 'ano meaning ng cancelled sa invoice', 'invoice status meaning po', 'ano ibig sabihin ng paid status', 'paid na ba pag sent', 'ano meaning ng cancelled status'],
                ],
                'kw' => 'invoice status, status meaning, meaning&sent, meaning&paid, meaning&cancel, sent&invoice, paid&invoice status, ibig sabihin&sent, ibig sabihin&paid, ibig sabihin&cancel, ibig sabihin&status, ano&status&invoice, invoice statuses, statuses, sent paid cancelled, invoice statuses, mga status ng invoice, mean&paid, mean&sent, mean&cancelled, mean&status, sent&paid, says cancelled, mean&invoice, ibig sabihin&cancelled, meaning&cancelled, cancelled status, meaning&cancelled&invoice',
                'en' => "Your invoice shows one of three statuses:\n\n- **Sent:** the invoice is ready and waiting for your payment.\n- **Paid:** it is fully paid.\n- **Cancelled:** it was cancelled, so it can no longer be paid. This happens after a cancellation request, or when the service request is closed.\n\nIf the invoice has a payment plan of two halves, it can show as half paid until the second half is done.",
                'tl' => "Isa po sa tatlong status ang makikita sa invoice:\n\n- **Sent:** handa na ang invoice at naghihintay ng bayad ninyo.\n- **Paid:** bayad na ito nang buo.\n- **Cancelled:** kinansela ito kaya hindi na ito mababayaran. Nangyayari ito pagkatapos ng cancellation request, o kapag isinara ang service request.\n\nKung may dalawang kalahati ang plano ng bayad, maaari itong lumabas na half paid hanggang matapos ang ikalawang kalahati.",
                'next' => ['luma_os_pay_how', 'luma_os_invoice_print', 'luma_os_refund_rule'],
            ],

            'luma_os_invoice_print' => [
                'b' => 6, 'title' => 'Print my invoice', 'title_tl' => 'I-print ang invoice',
                'say' => [
                    'en'  => ['can i print my invoice', 'is the invoice an official receipt', 'how do i print the invoice', 'i need a receipt', 'can i download my invoice', 'is this a receipt for my records'],
                    'tl'  => ['pwede bang i-print ang invoice', 'official receipt ba ang invoice', 'paano i-print ang invoice', 'kailangan ko ng resibo', 'pwede bang i-download ang invoice', 'resibo ba ito para sa records ko'],
                    'mix' => ['pano mag print ng invoice', 'official receipt ba yung invoice po', 'need ko ng resibo', 'pwede ba i-print ang invoice ko', 'download invoice paano', 'receipt ba ang invoice'],
                ],
                'kw' => 'print&invoice, invoice&print, i print&invoice, official receipt, official&receipt, receipt, resibo, download&invoice, copy&invoice, invoice copy, pdf&invoice, not an official receipt, paper&invoice',
                'en' => "Yes, you can print your invoice from the invoice page. Please note that the invoice is a bill and a record of your payment, but it is not an official receipt. If you need an official receipt for your records, please ask our team. {{contact}}",
                'tl' => "Opo, maaari po ninyong i-print ang invoice mula sa pahina ng invoice. Pakitandaan po na ang invoice ay singil at tala ng bayad ninyo, pero hindi ito official receipt. Kung kailangan ninyo ng official receipt para sa records, itanong po sa aming team. {{contact}}",
