                'kw' => 'gcash stuck, gcash&stuck, gcash&loading, gcash&pending, gcash&failed, gcash&error, gcash&not working, gcash&hindi gumagana, gcash&ayaw, gcash&umuusad, gcash&tagal, gcash&pumapalya, gcash&nagloading, gcash&nag loading, gcash&hindi nagbubukas, gcash&hindi nag open, gcash&cant open, gcash&keeps, gcash&problem, gcash&problema, stuck&payment, loading&payment, pending&payment, gcash&open, gcash&page, gcash&does not',
                'en' => "I'm sorry about the trouble. Please try these:\n\n1. Close the payment page and open your invoice again.\n2. Check that your GCash app is updated and has enough balance.\n3. Try again in a few minutes.\n\nIf you were already charged, please keep your reference number and contact our team before paying again. {{contact}}",
                'tl' => "Pasensya na po sa abala. Subukan po ito:\n\n1. Isara ang pahina ng bayad at buksan ulit ang invoice.\n2. Siguraduhing updated ang GCash app ninyo at may sapat na balance.\n3. Subukan ulit pagkalipas ng ilang minuto.\n\nKung nasingil na kayo, itabi ang reference number at kontakin ang aming team bago magbayad ulit. {{contact}}",
                'next' => ['luma_os_checkout_expired', 'luma_os_paid_still_unpaid', 'luma_os_card_declined'],
                'card' => true,
            ],

            'luma_os_card_declined' => [
                'b' => 7, 'title' => 'My card was declined', 'title_tl' => 'Na-decline ang card ko',
                'say' => [
                    'en'  => ['my card was declined', 'card payment failed', 'why was my card rejected', 'my credit card does not work for the invoice', 'card declined for repair payment', 'stripe payment failed'],
                    'tl'  => ['na-decline ang card ko', 'pumalya ang bayad sa card', 'bakit na-reject ang card ko', 'hindi gumagana ang credit card ko sa invoice', 'na-decline ang card sa bayad sa repair', 'pumalya ang bayad gamit ang card'],
                    'mix' => ['card declined po', 'card payment failed bakit', 'na reject ang card ko sa invoice', 'ayaw ng card ko sa payment', 'declined yung debit card ko', 'failed card payment'],
                ],
                'kw' => 'card declined, declined&card, declined, decline, card&rejected, card&failed, card&denied, card&hindi gumagana, card&not working, card&error, card&pumalya, card&ayaw, credit card&problem, debit card&problem, na decline, na-decline, na reject, na-reject, card payment failed, stripe&failed, stripe&error, card&work, card&does not work, credit card&invoice, card&declined',
                'en' => "I'm sorry. A card can be declined for reasons only your bank can see, such as a limit or an online-payment setting. Please try another card, or pay with GCash, or pay cash with our team. If money left your account but the invoice is still unpaid, contact our team with your reference number. {{contact}}",
                'tl' => "Pasensya na po. Maaaring ma-decline ang card dahil sa mga dahilang bangko lang ang nakakakita, tulad ng limit o setting para sa online na bayad. Subukan po ang ibang card, o mag-GCash, o magbayad ng cash sa aming team. Kung nabawasan ang account ninyo pero unpaid pa rin ang invoice, kontakin ang aming team dala ang reference number. {{contact}}",
                'next' => ['luma_os_pay_how', 'luma_os_gcash_stuck', 'luma_os_paid_still_unpaid'],
                'card' => true,
            ],

            'luma_os_pay_later' => [
                'b' => 7, 'title' => 'Can I pay later', 'title_tl' => 'Pwede bang mamaya na magbayad',
                'say' => [
                    'en'  => ['can i pay later', 'can i pay after the work is done', 'pay after the repair', 'can i delay my payment', 'do i have to pay now', 'pay when finished'],
                    'tl'  => ['pwede bang mamaya na ako magbayad', 'pwede bang magbayad pagkatapos ng trabaho', 'bayad pagkatapos ng repair', 'pwede bang ipagpaliban ang bayad', 'kailangan ko bang magbayad ngayon', 'magbabayad ako pag tapos na'],
                    'mix' => ['pay later pwede ba', 'pwede ba after na magbayad', 'bayad after ng repair pwede', 'kailangan ba magbayad agad', 'later na lang ang payment', 'pay when done pwede po'],
                ],
                'kw' => 'pay later, later&pay, mamaya&bayad, bayad&mamaya, pay after, after&pay, bayad&pagkatapos, delay&payment, ipagpaliban, pay now, magbayad ngayon, pay agad, bayad agad, pay when done, pay when finished, pay on completion, mag bayad pag tapos, magbabayad pag tapos, pag tapos&pay, later&payment, payment&later',
                'en' => "For Other Services, work starts only after you pay: the full amount, or the first half if your invoice has the half and half plan. So paying after the work is done is not possible, except for the second half, which you pay once the service is marked done. This is called no pay, no work.",
                'tl' => "Sa Other Services po, nagsisimula lamang ang trabaho pagkatapos ninyong magbayad: buo, o ang unang kalahati kung half and half ang plano ng invoice. Kaya hindi po maaaring magbayad pagkatapos ng trabaho, maliban sa ikalawang kalahati na babayaran kapag minarkahang tapos na ang serbisyo. Tinatawag itong no pay, no work.",
                'next' => ['luma_os_pay_full_half', 'luma_os_no_pay_no_work', 'luma_os_second_half'],
            ],

            'luma_os_pay_at_shop' => [
                'b' => 7, 'title' => 'Can I pay at the shop', 'title_tl' => 'Pwede bang sa shop magbayad',
                'say' => [
                    'en'  => ['can i pay at the shop', 'can i pay in cash', 'do you accept cash for repairs', 'pay cash in person', 'can i pay at your store', 'where do i pay cash'],
                    'tl'  => ['pwede bang sa shop magbayad', 'pwede bang cash', 'tumatanggap ba kayo ng cash sa repair', 'magbayad ng cash nang personal', 'pwede bang magbayad sa tindahan ninyo', 'saan ako magbabayad ng cash'],
                    'mix' => ['cash sa shop pwede po', 'pwede ba mag cash payment', 'bayad cash sa shop', 'accept ba kayo ng cash sa service', 'saan mag cash payment', 'cash po pwede ba'],
                ],
                'kw' => 'pay at the shop, pay at shop, pay in shop, pay cash, cash payment, cash&shop, cash&pay, sa shop&bayad, shop&bayad, bayad&cash, cash&tanggap, cash&accept, magbayad&cash, in person&pay, personal&bayad, pay&store, bayad&tindahan, tumatanggap&cash, accept&cash, can&cash',
                'en' => "Yes, you can pay cash. Please pay at our shop or to our team in person, and they will record it on your invoice. Shop hours are {{hours}}. A recorded cash payment counts the same as an online payment, and the work can start once the full amount (or the first half) is recorded. {{contact}}",
                'tl' => "Opo, maaari po kayong magbayad ng cash. Magbayad po sa shop namin o sa aming team nang personal at ire-record nila ito sa invoice ninyo. Ang oras ng shop ay {{hours}}. Pareho po ang bisa ng naka-record na cash sa online na bayad, at maaaring magsimula ang trabaho kapag na-record na ang buong halaga (o ang unang kalahati). {{contact}}",
                'next' => ['luma_os_no_pay_no_work', 'luma_os_pay_how', 'luma_os_min_payment'],
                'card' => true,
            ],

            'luma_os_no_pay_no_work' => [
                'b' => 7, 'title' => 'Why pay before the work', 'title_tl' => 'Bakit bayad muna bago gawin',
                'say' => [
                    'en'  => ['why can you not start without payment', 'why do i have to pay before the work starts', 'why pay first', 'no pay no work', 'can you start the work before i pay', 'why does the work wait for my payment'],
                    'tl'  => ['bakit hindi kayo makapagsimula nang walang bayad', 'bakit kailangang magbayad bago simulan', 'bakit bayad muna', 'no pay no work po', 'pwede bang simulan bago ako magbayad', 'bakit hinihintay ang bayad ko'],
                    'mix' => ['bakit need pay first bago start', 'no pay no work ba kayo', 'pwede ba start work bago bayad', 'why bayad muna po', 'bakit hindi pa nagsisimula kasi walang bayad', 'bakit hinihintay pa payment'],
                ],
                'kw' => 'no pay no work, pay first, bayad muna, bago magbayad, before pay, before payment, without payment, without paying, nang walang bayad, walang bayad&simula, why&pay&first, bakit&bayad&muna, bakit&bayad&bago, start&before&pay, simulan&bago&bayad, work starts after, start after payment, hinihintay&bayad, wait&payment, hinihintay&payment, paid&start, start&paid',
                'en' => "Our rule is no pay, no work. We start the work only after your payment is in: the full amount, or the first half if your invoice has the half and half plan. This lets us buy materials and set aside the laborer for your job. The second half is paid when the service is done.",
                'tl' => "Ang patakaran po namin ay no pay, no work. Sinisimulan lamang namin ang trabaho pagkatapos pumasok ang bayad ninyo: buo, o ang unang kalahati kung half and half ang plano ng invoice. Nakakatulong ito para makabili kami ng materyales at maitabi ang laborer para sa trabaho ninyo. Ang ikalawang kalahati ay babayaran kapag tapos na ang serbisyo.",
                'next' => ['luma_os_pay_how', 'luma_os_pay_full_half', 'luma_os_duration'],
            ],

            /* ───────── 8. Cancelling and refunds ───────── */

            'luma_os_refund_rule' => [
                'b' => 8, 'title' => 'Refund rules', 'title_tl' => 'Patakaran sa refund',
                'say' => [
                    'en'  => ['what is your refund policy for repairs', 'can i get a refund on my service', 'when can i cancel my service request', 'refund rules for other services', 'am i allowed to cancel after paying', 'what are the cancellation rules'],
                    'tl'  => ['ano ang patakaran ninyo sa refund ng repair', 'pwede ba akong ma-refund sa serbisyo', 'kailan ko pwedeng kanselahin ang request', 'patakaran sa refund ng other services', 'pwede bang magkansela pagkatapos magbayad', 'ano ang mga patakaran sa pagkansela'],
                    'mix' => ['refund policy ng other services', 'pwede ba refund sa repair', 'cancel rules po sa service request', 'pwede mag cancel after payment', 'ano rules sa refund po', 'refund rules ng service'],
                ],
                'kw' => 'refund policy, refund rules, refund rule, rules&refund, policy&refund, cancellation rules, cancel rules, cancel policy, patakaran&refund, patakaran&cancel, patakaran&kansel, can&refund&service, can&refund&repair, refund&service, refund&repair, refund&other service, refund&ticket, cancel&service request, cancel&ticket, cancel&other service, cancel&after&pay, cancel&repair, cancel&service, pwede&refund&repair, pwede&refund&service, allowed&cancel, when can i cancel, kailan&cancel, cancel&pagkatapos, cancel&after payment, cancel&pagkatapos&pay, cancel&after paying, cancel&after pay',
                'en' => "Here is how it works. If the work has not started, you can ask to cancel, and if our team accepts the request before work starts, the full amount you paid is sent back to you. Once the laborer has started the work, it is non-refundable, but you can still send a request and our team will review it and reply. Refunds go back by GCash or cash, whichever you choose (even if you paid by card), within {{refund_days}} days after our team confirms the request.",
                'tl' => "Ganito po ang patakaran. Kung hindi pa nagsisimula ang trabaho, maaari kayong humiling na magkansela, at kung tatanggapin ng aming team ang request bago magsimula ang trabaho, ibabalik sa inyo ang buong halagang binayaran ninyo. Kapag nagsimula na ang laborer, hindi na ito refundable, pero maaari pa rin kayong magpadala ng request at susuriin ito ng aming team at sasagot sila. Ibinabalik ang refund sa GCash o cash, alinman ang piliin ninyo (kahit card ang ginamit ninyo sa pagbayad), sa loob ng {{refund_days}} araw pagkatapos kumpirmahin ng aming team ang request.",
                'next' => ['luma_os_work_started_meaning', 'luma_os_refund_how', 'luma_os_refund_timeline', 'luma_os_refund_after_start'],
                'buttons' => [['Read the Other Services terms', 'Basahin ang terms ng Other Services', 'services.terms']],
            ],

            'luma_os_work_started_meaning' => [
                'b' => 8, 'title' => 'What does started mean', 'title_tl' => 'Ano ang ibig sabihin ng nagsimula',
                'say' => [
                    'en'  => ['what does work started mean', 'how do i know if the work has started', 'when is work considered started', 'what counts as started', 'what does started mean for my ticket', 'has the work started on my ticket'],
                    'tl'  => ['ano ang ibig sabihin ng nagsimula na ang trabaho', 'paano ko malalaman kung nagsimula na', 'kailan masasabing nagsimula na ang trabaho', 'ano ang itinuturing na nagsimula', 'ano ang kahulugan ng nagsimula na', 'nagsimula na ba ang trabaho sa ticket ko'],
                    'mix' => ['work started meaning po', 'paano malaman kung started na', 'kailan considered started ang work', 'started na ba ang work ko', 'ano ibig sabihin ng started', 'what counts as work started'],
                ],
                'kw' => 'work started, started&mean, meaning&started, started&work, nagsimula na, nagsimula&trabaho, started na, already started, nasimulan, simula ng trabaho, considered started, counts as started, laborer started, laborer&start, paano&malaman&start',
                'en' => "Work counts as started when our team taps Work started on your ticket, which means the laborer has begun the job (for example the materials are bought or the repair is under way). You will see this on your ticket and get a notification. Before that, the work has not started, and a cancellation can still be refunded.",
                'tl' => "Itinuturing pong nagsimula ang trabaho kapag pinindot ng aming team ang Work started sa ticket ninyo, ibig sabihin ay nasimulan na ng laborer ang trabaho (halimbawa, nabili na ang materyales o umuusad na ang pagpapaayos). Makikita ninyo ito sa ticket at makakatanggap kayo ng notification. Bago iyon, hindi pa nagsisimula ang trabaho at maaari pang ma-refund ang pagkansela.",
                'next' => ['luma_os_refund_rule', 'luma_os_check_status', 'luma_os_refund_how'],
