            'luma_os_wrong_gcash' => [
                'b' => 8, 'title' => 'Wrong GCash number', 'title_tl' => 'Maling GCash number',
                'say' => [
                    'en'  => ['i entered the wrong gcash number', 'wrong gcash number in my refund request', 'how do i fix my gcash number', 'the refund went to the wrong number', 'my gcash number was typed wrong', 'can i change the gcash number for my refund'],
                    'tl'  => ['nagkamali ako ng gcash number', 'maling gcash number sa refund request ko', 'paano ayusin ang gcash number ko', 'napunta sa maling number ang refund', 'mali ang nai-type kong gcash number', 'pwede bang palitan ang gcash number ng refund'],
                    'mix' => ['mali yung gcash number ko', 'wrong gcash number po sa refund', 'pano palitan ang gcash number sa request', 'nagkamali ako ng number sa refund', 'maling number ang gcash ko', 'change gcash number paano'],
                ],
                'kw' => 'wrong gcash, wrong&gcash number, mali&gcash, maling gcash, gcash&mali, gcash&wrong, gcash&maling, number&mali, number&wrong, change&gcash number, palitan&gcash, baguhin&gcash, fix&gcash, gcash&typo, gcash&nagkamali, gcash number&incorrect, wrong number&refund, refund&wrong number, refund&maling number, refund problem, refund&hindi pumasok, refund&did not arrive, ayusin&gcash number, gcash number&request',
                'en' => "No worries, this can be fixed while your request is still open. Open your refund request page and send our team the correct GCash number and the name on the account in a reply. Please check both carefully, because once a refund is sent, it cannot be recalled or sent again.",
                'tl' => "Huwag po kayong mag-alala, maaari itong ayusin habang bukas pa ang request ninyo. Buksan ang pahina ng refund request at ipadala sa aming team ang tamang GCash number at ang pangalan sa account sa isang reply. Pakisuri po nang mabuti ang dalawa, dahil kapag naipadala na ang refund, hindi na ito maibabalik o maipapadala ulit.",
                'next' => ['luma_os_refund_status', 'luma_os_refund_timeline'],
                'handler' => 'status_refund',
            ],

            'luma_os_refund_declined' => [
                'b' => 8, 'title' => 'My request was declined', 'title_tl' => 'Na-decline ang request ko',
                'say' => [
                    'en'  => ['my refund request was declined', 'why was my cancellation declined', 'they rejected my refund', 'refund denied', 'what can i do if my refund is declined', 'i got a decline message for my request'],
                    'tl'  => ['na-decline ang refund request ko', 'bakit hindi tinanggap ang pagkansela ko', 'tinanggihan ang refund ko', 'hindi pinayagan ang refund', 'ano ang magagawa ko kung tinanggihan ang refund', 'nakatanggap ako ng decline sa request ko'],
                    'mix' => ['declined ang refund request ko', 'bakit declined ang cancellation', 'rejected daw ang refund ko', 'refund denied po bakit', 'ano gagawin kung declined ang request', 'na decline yung request ko'],
                ],
                'kw' => 'refund declined, declined&refund, declined&request, declined&cancel, rejected&refund, rejected&request, denied&refund, refund&denied, tinanggihan, hindi pinayagan, hindi tinanggap&refund, na decline&request, na-decline&request, decline&refund, decline&cancellation, decline message, refund&reject, why&declined, bakit&declined, bakit&tinanggihan, tinanggap&cancel, hindi tinanggap',
                'en' => "I'm sorry this was not the answer you hoped for. When a request is declined, our team writes the reason on your refund request page, usually because the work had already started. Please open it to read their reply. If you want to talk about it, or you have more details to share, you can reply there or contact our team. {{contact}}",
                'tl' => "Pasensya na po kung hindi ito ang inaasahan ninyong sagot. Kapag na-decline ang request, isinusulat ng aming team ang dahilan sa pahina ng refund request ninyo, kadalasan dahil nagsimula na ang trabaho. Buksan po ito para mabasa ang sagot nila. Kung gusto ninyong pag-usapan o may dagdag kayong detalye, maaari kayong mag-reply doon o kontakin ang aming team. {{contact}}",
                'next' => ['luma_os_refund_after_start', 'luma_os_refund_status'],
                'handler' => 'status_refund',
                'card' => true,
            ],

            'luma_os_refund_after_start' => [
                'b' => 8, 'title' => 'Refund after work started', 'title_tl' => 'Refund kapag nagsimula na',
                'say' => [
                    'en'  => ['can i get a refund after the work has started', 'work already started can i still cancel', 'the laborer already began can i get my money back', 'refund after the repair started', 'is it non refundable once started', 'can i still send a request if work started'],
                    'tl'  => ['pwede pa bang ma-refund kung nagsimula na ang trabaho', 'nagsimula na ang trabaho pwede pa bang magkansela', 'nagsimula na ang laborer pwede pa bang ibalik ang pera', 'refund pagkatapos magsimula ang repair', 'hindi na ba refundable kapag nagsimula na', 'pwede pa bang magpadala ng request kahit nagsimula na'],
                    'mix' => ['started na ang work pwede pa refund', 'refund after work started po', 'nagstart na ang laborer pwede pa cancel', 'non-refundable na ba pag started', 'pwede pa mag request kahit started na', 'refund pwede pa ba kahit nasimulan na'],
                ],
                'kw' => 'refund&started, started&refund, refund&after start, refund&nagsimula, nagsimula&refund, nagsimula&kansel, nagsimula&cancel, started&cancel, cancel&started, cancel&after start, non refundable, nonrefundable, hindi refundable, no refund, walang refund, already started, nagsimula na&refund, laborer&started&refund, laborer&refund, laborer&nagsimula, request&started, request&nagsimula, laborer&started, send&request&started, refund&start, still&send&request, refund&pagkatapos&start',
                'en' => "Once the laborer has started, the work is usually non-refundable, because the time and materials are already used. You can still send a request, and our team will review it and reply to you. I cannot say what the answer will be. Sending a request does not cost anything.",
                'tl' => "Kapag nagsimula na ang laborer, karaniwang hindi na refundable ang trabaho dahil nagamit na ang oras at materyales. Maaari pa rin po kayong magpadala ng request, susuriin ito ng aming team at sasagot sila sa inyo. Hindi ko po masasabi kung ano ang magiging sagot. Walang bayad ang pagpapadala ng request.",
                'next' => ['luma_os_refund_how', 'luma_os_work_started_meaning', 'luma_os_refund_status'],
                'buttons' => [['Read the Other Services terms', 'Basahin ang terms ng Other Services', 'services.terms']],
            ],

            'luma_os_cancel_unpaid' => [
                'b' => 8, 'title' => 'Cancel when nothing is paid', 'title_tl' => 'Kanselahin kung wala pang bayad',
                'say' => [
                    'en'  => ['i have not paid yet can i cancel', 'cancel my ticket i did not pay anything', 'can i cancel an unpaid invoice', 'cancel before paying', 'i never paid so cancel it', 'is there a fee to cancel if i have not paid'],
                    'tl'  => ['hindi pa ako nagbabayad pwede bang magkansela', 'kanselahin ang ticket ko wala pa akong binabayaran', 'pwede bang kanselahin ang invoice na hindi pa bayad', 'magkansela bago magbayad', 'hindi ako nagbayad kaya kanselahin', 'may bayad ba ang pagkansela kung hindi pa ako nagbabayad'],
                    'mix' => ['cancel ko na lang di pa ako nagbabayad', 'wala pa akong bayad pwede ba cancel', 'cancel ticket kahit unpaid', 'unpaid pa invoice ko pwede cancel', 'cancel before payment pwede', 'may fee ba pag nagcancel ng unpaid'],
