    /** node id => ['en' => title, 'tl' => title_tl] for every node (the follow-up chips). */
    public static function titles(): array
    {
        $out = [];
        foreach (self::nodes() as $id => $node) {
            $out[$id] = ['en' => $node['title'], 'tl' => $node['title_tl']];
        }

        return $out;
    }

    /** English chip text => Tagalog chip text, for Luma::chips(). */
    public static function chipTranslations(): array
    {
        $map = [];
        foreach (self::nodes() as $node) {
            $map[$node['title']] = $node['title_tl'];
        }

        return $map;
    }
}
